const STOP = {};
"the and for are what how why does that this with you your from have has not can will would should could about into when then than there their they them was were been being which who whom its our out all any but just like want need tell give explain please example examples mean means meaning".split(" ").forEach(w => { STOP[w] = 1; });
function stem(w) {
  const m = w.match(/^(.{3,}?)(ing|ed|es|ly|s)$/);
  return m && w.length > 4 ? m[1] : w;
}
function toks(s) {
  const o = {};
  String(s).toLowerCase().replace(/[^a-z0-9%]+/g, " ").split(" ").forEach(w => { if (w.length > 2 && !STOP[w]) o[stem(w)] = 1; });
  return o;
}
function hasTok(set, w) {
  if (set[w]) return true;
  if (w.length < 4) return false;
  for (const k in set) { if (k.length >= 4 && (k.indexOf(w) === 0 || w.indexOf(k) === 0)) return true; }
  return false;
}
KB.forEach(k => { k._t = toks(k.t); k._x = toks(k.x); });
function scoreEntry(e, qt, qlow, grade) {
  let s = 0;
  for (const w in qt) { if (hasTok(e._t, w)) s += 3; else if (hasTok(e._x, w)) s += 1; }
  if (s && qlow.indexOf(e.t.toLowerCase()) >= 0) s += 5;
  if (s && grade && e.g === grade) s += 2;
  return s;
}
function retrieve(mode, q) {
  const qt = toks(q), ql = q.toLowerCase(), gm = ql.match(/grade\s*(10|11|12)/), grade = gm ? +gm[1] : 0;
  const res = [];
  KB.forEach(k => { if (k.a !== mode) return; const s = scoreEntry(k, qt, ql, grade); if (s > 0) res.push([s, k]); });
  res.sort((a, b) => b[0] - a[0]);
  return res.slice(0, mode === "pmo" ? 4 : 5).map(r => r[1]);
}
function relevantNotes(mode, q, notes) {
  const all = notes.filter(n => n.area === mode || n.area === "all").map(n => ({ t: n.topic, x: n.body, _t: toks(n.topic), _x: toks(n.body) }));
  if (all.length <= 6) return all;
  const qt = toks(q), ql = q.toLowerCase();
  const sc = all.map((n, i) => [scoreEntry(n, qt, ql, 0) * 10 - i, n]);
  sc.sort((a, b) => b[0] - a[0]);
  return sc.slice(0, 6).map(r => r[1]);
}
function buildSystem(mode, q, prev, notes) {
  const qq = (q.length < 30 && prev) ? prev + " " + q : q;
  let s = RULES.replace("{MODE}", MODES[mode].label) + "\n" + MODES[mode].extra;
  if (mode === "pmo") s += "\n\nConfirmed facts about PMO (use only these for questions about the organization):\n" + FACTS_PMO;
  if (mode === "eco") s += "\n\nConfirmed facts about Economist OJUKU:\n" + FACTS_OJUKU;
  const nt = relevantNotes(mode, qq, notes);
  if (nt.length) s += "\n\nLatest notes from the teacher (they win if they differ from older material):\n" + nt.map(n => "- " + n.t + ": " + n.x).join("\n");
  const ctx = retrieve(mode, qq);
  if (ctx.length) s += "\n\nREFERENCE from the course materials:\n" + ctx.map(k => "[" + k.t + (k.g ? " (Grade " + k.g + ")" : "") + "]\n" + k.x).join("\n\n");
  else s += "\n\nREFERENCE: no matching course notes were found for this question. Answer carefully from standard school-level knowledge, or say you are not sure.";
  return { system: s, covered: ctx.length > 0 || nt.length > 0 };
}

// ---------- small helpers ----------
const JSON_HEADERS = { "content-type": "application/json; charset=utf-8", "cache-control": "no-store" };
function json(obj, status) { return new Response(JSON.stringify(obj), { status: status || 200, headers: JSON_HEADERS }); }
function err(status, msg) { return json({ error: msg }, status); }
const enc = new TextEncoder();
function b64url(buf) {
  let s = ""; const b = new Uint8Array(buf);
  for (let i = 0; i < b.length; i++) s += String.fromCharCode(b[i]);
  return btoa(s).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");
}
async function hmac(secret, msg) {
  const key = await crypto.subtle.importKey("raw", enc.encode(secret), { name: "HMAC", hash: "SHA-256" }, false, ["sign"]);
  return b64url(await crypto.subtle.sign("HMAC", key, enc.encode(msg)));
}
function same(a, b) {
  if (a.length !== b.length) return false;
  let r = 0; for (let i = 0; i < a.length; i++) r |= a.charCodeAt(i) ^ b.charCodeAt(i);
  return r === 0;
}
function dayOf(ts) { return new Date(ts).toISOString().slice(0, 10); }

let schemaReady = false;
async function ensureSchema(env) {
  if (schemaReady) return;
  await env.DB.batch([
    env.DB.prepare("CREATE TABLE IF NOT EXISTS logs(id INTEGER PRIMARY KEY AUTOINCREMENT, ts INTEGER, visitor TEXT, nick TEXT, mode TEXT, q TEXT, a TEXT, matched INTEGER, country TEXT)"),
    env.DB.prepare("CREATE INDEX IF NOT EXISTS logs_ts ON logs(ts)"),
    env.DB.prepare("CREATE INDEX IF NOT EXISTS logs_visitor ON logs(visitor)"),
    env.DB.prepare("CREATE TABLE IF NOT EXISTS notes(id INTEGER PRIMARY KEY AUTOINCREMENT, ts INTEGER, area TEXT, topic TEXT, body TEXT)"),
    env.DB.prepare("CREATE TABLE IF NOT EXISTS quiz(id INTEGER PRIMARY KEY AUTOINCREMENT, ts INTEGER, s TEXT, g INTEGER, q TEXT, o TEXT, a INTEGER, e TEXT)"),
    env.DB.prepare("CREATE TABLE IF NOT EXISTS rl(k TEXT PRIMARY KEY, n INTEGER)")
  ]);
  schemaReady = true;
}
async function bump(env, key) {
  const r = await env.DB.prepare("INSERT INTO rl(k,n) VALUES(?,1) ON CONFLICT(k) DO UPDATE SET n=n+1 RETURNING n").bind(key).first();
  return r ? r.n : 1;
}

// ---------- public API ----------
async function chat(request, env) {
  let body; try { body = await request.json(); } catch (e) { return err(400, "Bad request"); }
  const mode = body.mode;
  if (!MODES[mode]) return err(400, "Bad topic");
  let msgs = Array.isArray(body.messages) ? body.messages.slice(-11) : [];
  msgs = msgs.filter(m => m && (m.role === "user" || m.role === "assistant") && typeof m.content === "string" && m.content.trim())
    .map(m => ({ role: m.role, content: m.content.slice(0, m.role === "user" ? 800 : 4000) }));
  while (msgs.length && msgs[0].role !== "user") msgs.shift();
  if (!msgs.length || msgs[msgs.length - 1].role !== "user") return err(400, "Bad question");
  const q = msgs[msgs.length - 1].content.trim();
  const visitor = String(body.visitor || "").replace(/[^a-z0-9-]/gi, "").slice(0, 40) || "unknown";
  const nick = String(body.nick || "").replace(/[\u0000-\u001f<>]/g, "").trim().slice(0, 40);
  const ip = request.headers.get("cf-connecting-ip") || "0";
  const day = dayOf(Date.now());

  await ensureSchema(env);
  const vLimit = +env.VISITOR_LIMIT || 40, gLimit = +env.DAILY_LIMIT || 500;
  if (await bump(env, "v:" + visitor + ":" + day) > vLimit) return err(429, "daily_limit");
  if (await bump(env, "ip:" + ip + ":" + day) > vLimit * 6) return err(429, "daily_limit");
  if (await bump(env, "g:" + day) > gLimit) return err(429, "busy");

  const notesRes = await env.DB.prepare("SELECT area,topic,body FROM notes ORDER BY id DESC LIMIT 200").all();
  let prev = null;
  for (let i = msgs.length - 3; i >= 0; i -= 2) { if (msgs[i].role === "user") { prev = msgs[i].content; break; } }
  const built = buildSystem(mode, q, prev, notesRes.results || []);

  let text = "";
  try {
    const r = await fetch("https://api.anthropic.com/v1/messages", {
      method: "POST",
      headers: { "content-type": "application/json", "x-api-key": env.ANTHROPIC_API_KEY, "anthropic-version": "2023-06-01" },
      body: JSON.stringify({ model: env.MODEL || "claude-sonnet-5-5", max_tokens: 800, system: built.system, messages: msgs })
    });
    if (!r.ok) {
      console.log("anthropic error", r.status, (await r.text()).slice(0, 300));
      return err(502, "ai_unavailable");
    }
    const j = await r.json();
    text = (j.content || []).filter(b => b.type === "text").map(b => b.text).join("\n").trim();
  } catch (e) {
    console.log("anthropic fetch failed", String(e));
    return err(502, "ai_unavailable");
  }
  if (!text) return err(502, "ai_unavailable");

  try {
    await env.DB.prepare("INSERT INTO logs(ts,visitor,nick,mode,q,a,matched,country) VALUES(?,?,?,?,?,?,?,?)")
      .bind(Date.now(), visitor, nick, mode, q, text.slice(0, 4000), built.covered ? 1 : 0, (request.cf && request.cf.country) || "").run();
  } catch (e) { console.log("log failed", String(e)); }
  return json({ text });
}

async function content(env) {
  await ensureSchema(env);
  const n = await env.DB.prepare("SELECT id,area,topic,body,ts FROM notes ORDER BY id DESC LIMIT 300").all();
  const x = await env.DB.prepare("SELECT id,s,g,q,o,a,e,ts FROM quiz ORDER BY id DESC LIMIT 500").all();
  const quiz = (x.results || []).map(r => { let o = []; try { o = JSON.parse(r.o); } catch (e) {} return { id: "x" + r.id, s: r.s, g: r.g, q: r.q, o, a: r.a, e: r.e || "", ts: r.ts }; });
  return json({ notes: n.results || [], quiz });
}

// ---------- admin API ----------
async function login(request, env) {
  if (!env.ADMIN_PASSWORD) return err(500, "Admin password is not set");
  await ensureSchema(env);
  const ip = request.headers.get("cf-connecting-ip") || "0";
  if (await bump(env, "login:" + ip + ":" + new Date().toISOString().slice(0, 13)) > 10) return err(429, "Too many tries. Wait an hour.");
  let body; try { body = await request.json(); } catch (e) { return err(400, "Bad request"); }
  const a = await hmac("cmp", String(body.password || "")), b = await hmac("cmp", env.ADMIN_PASSWORD);
  if (!same(a, b)) return err(401, "Wrong password");
  const exp = Date.now() + 12 * 3600 * 1000;
  return json({ token: exp + "." + await hmac(env.ADMIN_PASSWORD, "ojuku-admin|" + exp) });
}
async function authed(request, env) {
  const h = request.headers.get("authorization") || "";
  const t = h.startsWith("Bearer ") ? h.slice(7) : "";
  const i = t.indexOf(".");
  if (i < 1 || !env.ADMIN_PASSWORD) return false;
  const exp = +t.slice(0, i);
  if (!(exp > Date.now())) return false;
  return same(t.slice(i + 1), await hmac(env.ADMIN_PASSWORD, "ojuku-admin|" + exp));
}
async function admin(request, env, path) {
  await ensureSchema(env);
  const url = new URL(request.url), m = request.method;
  const DB = env.DB;
  if (path === "/api/admin/stats" && m === "GET") {
    const now = Date.now(), today = new Date(dayOf(now) + "T00:00:00Z").getTime();
    const one = async (sql, ...b) => (await DB.prepare(sql).bind(...b).first()) || {};
    const total = (await one("SELECT COUNT(*) n FROM logs")).n || 0;
    const td = (await one("SELECT COUNT(*) n FROM logs WHERE ts>=?", today)).n || 0;
    const wk = (await one("SELECT COUNT(*) n FROM logs WHERE ts>=?", today - 6 * 86400000)).n || 0;
    const vis = (await one("SELECT COUNT(DISTINCT visitor) n FROM logs")).n || 0;
    const unm = (await one("SELECT COUNT(*) n FROM logs WHERE matched=0")).n || 0;
    const byMode = (await DB.prepare("SELECT mode, COUNT(*) n FROM logs GROUP BY mode").all()).results || [];
    const daily = (await DB.prepare("SELECT strftime('%Y-%m-%d', ts/1000, 'unixepoch') d, COUNT(*) n FROM logs WHERE ts>=? GROUP BY d ORDER BY d").bind(today - 13 * 86400000).all()).results || [];
    const students = (await DB.prepare("SELECT l.visitor visitor, COUNT(*) n, MAX(l.ts) last, (SELECT nick FROM logs x WHERE x.visitor=l.visitor AND x.nick!='' ORDER BY x.ts DESC LIMIT 1) nick FROM logs l GROUP BY l.visitor ORDER BY n DESC LIMIT 100").all()).results || [];
    return json({ total, today: td, week: wk, visitors: vis, unmatched: unm, byMode, daily, students });
  }
  if (path === "/api/admin/logs" && m === "GET") {
    const p = url.searchParams, where = [], b = [];
    if (p.get("mode")) { where.push("mode=?"); b.push(p.get("mode")); }
    if (p.get("unmatched") === "1") where.push("matched=0");
    if (p.get("visitor")) { where.push("visitor=?"); b.push(p.get("visitor")); }
    if (p.get("search")) { where.push("q LIKE ?"); b.push("%" + p.get("search").slice(0, 60) + "%"); }
    const limit = Math.min(+p.get("limit") || 100, 300), offset = Math.max(+p.get("offset") || 0, 0);
    const sql = "SELECT id,ts,visitor,nick,mode,q,a,matched,country FROM logs" + (where.length ? " WHERE " + where.join(" AND ") : "") + " ORDER BY id DESC LIMIT ? OFFSET ?";
    const r = await DB.prepare(sql).bind(...b, limit, offset).all();
    return json({ rows: r.results || [] });
  }
  let mm;
  if ((mm = path.match(/^\/api\/admin\/logs\/(\d+)$/)) && m === "DELETE") { await DB.prepare("DELETE FROM logs WHERE id=?").bind(+mm[1]).run(); return json({ ok: true }); }
  if (path === "/api/admin/notes" && m === "POST") {
    let b; try { b = await request.json(); } catch (e) { return err(400, "Bad request"); }
    const area = ["eco", "math", "pmo", "all"].includes(b.area) ? b.area : "all";
    const topic = String(b.topic || "").trim().slice(0, 120), body = String(b.body || "").trim().slice(0, 3000);
    if (!topic || !body) return err(400, "Write a topic and the information.");
    const r = await DB.prepare("INSERT INTO notes(ts,area,topic,body) VALUES(?,?,?,?)").bind(Date.now(), area, topic, body).run();
    return json({ ok: true, id: r.meta && r.meta.last_row_id });
  }
  if ((mm = path.match(/^\/api\/admin\/notes\/(\d+)$/)) && m === "DELETE") { await DB.prepare("DELETE FROM notes WHERE id=?").bind(+mm[1]).run(); return json({ ok: true }); }
  if (path === "/api/admin/quiz" && m === "POST") {
    let b; try { b = await request.json(); } catch (e) { return err(400, "Bad request"); }
    const o = Array.isArray(b.o) ? b.o.map(x => String(x || "").trim().slice(0, 200)) : [];
    const q = String(b.q || "").trim().slice(0, 400);
    if (!q || o.length !== 4 || o.some(x => !x)) return err(400, "Write the question and all four answers.");
    if (new Set(o.map(x => x.toLowerCase())).size < 4) return err(400, "The four answers must be different.");
    const a = +b.a; if (!(a >= 0 && a < 4)) return err(400, "Choose the correct answer.");
    const g = [10, 11, 12].includes(+b.g) ? +b.g : 10, s = b.s === "math" ? "math" : "eco";
    await DB.prepare("INSERT INTO quiz(ts,s,g,q,o,a,e) VALUES(?,?,?,?,?,?,?)").bind(Date.now(), s, g, q, JSON.stringify(o), a, String(b.e || "").trim().slice(0, 500)).run();
    return json({ ok: true });
  }
  if ((mm = path.match(/^\/api\/admin\/quiz\/(\d+)$/)) && m === "DELETE") { await DB.prepare("DELETE FROM quiz WHERE id=?").bind(+mm[1]).run(); return json({ ok: true }); }
  return err(404, "Not found");
}

export default {
  async fetch(request, env) {
    const url = new URL(request.url), path = url.pathname;
    if (!path.startsWith("/api/")) return env.ASSETS.fetch(request);
    try {
      if (path === "/api/chat" && request.method === "POST") return await chat(request, env);
      if (path === "/api/content" && request.method === "GET") return await content(env);
      if (path === "/api/admin/login" && request.method === "POST") return await login(request, env);
      if (path.startsWith("/api/admin/")) {
        if (!(await authed(request, env))) return err(401, "Please sign in");
        return await admin(request, env, path);
      }
      return err(404, "Not found");
    } catch (e) {
      console.log("worker error", String(e && e.stack || e));
      return err(500, "Something went wrong");
    }
  }
};
